  ('97a34f51-2804-4e24-8780-6fed2c2546ae', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रसाद मिश्र का जन््म सन् 1913 में मध््य प्रदेश के होशंगाबाद (अब नर्मदापुरम) में हुआ था। साहित््य के साथ-साथ स्वाधीनता आंदोलन में जिन कवियोों की सक्रियय भागीदारी थी, उनमें यये प्रमुख हैं। उनकी मुख््य रचनाएँ— गीत-फ़रोश, खुशबू के शिलालेख, चकित है दुख, अँधेरी कविताएँ, बुनी हुई रस््सी, कवितांतर, शतदल, गांधी-पंचशती, त्रिकाल ससंध््या आदि हैं। बुनी हुई रस््सी (कविता संग्रह) पर उन््हें साहित््य अकादमी पुरस्कार मिला है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('25b78028-cac6-489f-a0f9-dc69fe1ce4db', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रसाद मिश्र ने राष्‍ट्रभाषा प्रचार समिति में कार््य कियया और सन् 1952–55 तक हैदराबाद से प्रकाशित हिंदी की लोकप्रियय साहित््ययिक पत्रिका कल्पना का संपादन भी कियया। सन् 1955–58 के बीच वे आकाशवाणी के हिंदी कार््यक्रमों से संबद्ध रहे। उन््होंने ससंपूर््ण गांधी वाङ्मयय का भी संपादन कियया। सन् 1985 में उनका निधन हो गयया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('7153a021-623d-4097-8df9-2a94a0802941', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रससाद मिश्र ने ससन् 1942 के ‘भारत छोड़ो आंदोलन’ में सक्रियय रूप ससे भाग लियया जिससके चलते ब्रिटिश ससरकार ने उन््हें तीन वर््ष के लिए कारावासस का दंड दियया। 1942 के स््ववाधीनता आंदोलन के ससमयय जेल में रहते हुए ही उन््होंने ‘घर की ययाद’ कविता लिखी। परिवार की स्ममृति ही इसस कविता की केेंद्रीयय ससंवेदना है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('04ee1777-f173-4ea2-8d7a-16a3bbb4c960', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कारावासस के ससमयय घर को ययाद करते हुए कवि की स्ममृति में उनके परिजन एक-एक करके सम्‍म‍िलित होते चले जाते हैं। कवि ससावन के बादल द्ारा परिवार को ससंदेश भेज रहा है और उसससे आग्रह करता है कि वह उन््हें जेल के कष्‍टों के विषयय में न बताए और ससांत््वना दे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
