  ('21cceb82-2e65-43c8-afdb-a52b853e0eed', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पाँचवें को वे न तरसें।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c1f22fd7-7c0c-49d7-ac56-7ffa1f1ede98', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$खुद न समझूँ कौन हूँ मैं,$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c723db77-c981-49c7-b82e-6986e046701a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रसाद मिश्र का जन््म सन् 1913 में मध््य प्रदेश के होशंगाबाद (अब नर्मदापुरम) में हुआ था। साहित््य के साथ-साथ स्वाधीनता आंदोलन में जिन कवियोों की सक्रियय भागीदारी थी, उनमें यये प्रमुख हैं। उनकी मुख््य रचनाएँ— गीत-फ़रोश, खुशबू के शिलालेख, चकित है दुख, अँधेरी कविताएँ, बुनी हुई रस््सी, कवितांतर, शतदल, गांधी-पंचशती, त्रिकाल ससंध््या आदि हैं। बुनी हुई रस््सी (कविता संग्रह) पर उन््हें साहित््य अकादमी पुरस्कार मिला है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('e0e13c1b-9632-421b-9c3d-9c14b555ee82', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रसाद मिश्र ने राष्‍ट्रभाषा प्रचार समिति में कार््य कियया और सन् 1952–55 तक हैदराबाद से प्रकाशित हिंदी की लोकप्रियय साहित््ययिक पत्रिका कल्पना का संपादन भी कियया। सन् 1955–58 के बीच वे आकाशवाणी के हिंदी कार््यक्रमों से संबद्ध रहे। उन््होंने ससंपूर््ण गांधी वाङ्मयय का भी संपादन कियया। सन् 1985 में उनका निधन हो गयया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('4ad19370-6802-407a-9c61-517100bfc842', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रससाद मिश्र ने ससन् 1942 के ‘भारत छोड़ो आंदोलन’ में सक्रियय रूप ससे भाग लियया जिससके चलते ब्रिटिश ससरकार ने उन््हें तीन वर््ष के लिए कारावासस का दंड दियया। 1942 के स््ववाधीनता आंदोलन के ससमयय जेल में रहते हुए ही उन््होंने ‘घर की ययाद’ कविता लिखी। परिवार की स्ममृति ही इसस कविता की केेंद्रीयय ससंवेदना है। कारावासस के ससमयय घर को ययाद करते हुए कवि की स्ममृति में उनके परिजन एक-एक करके सम्‍म‍िलित होते चले जाते हैं। कवि ससावन के बादल द्ारा परिवार को ससंदेश भेज रहा है और उसससे आग्रह करता है कि वह उन््हें जेल के कष्‍टों के विषयय में न बताए और ससांत््वना दे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('10786dcc-3b6a-4cc2-a6d8-0e6406740d97', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रसाद मिश्र का जन््म सन् 1913 में मध््य प्रदेश के होशंगाबाद (अब नर्मदापुरम) में हुआ था। साहित््य के साथ-साथ स्वाधीनता आंदोलन में जिन कवियोों की सक्रियय भागीदारी थी, उनमें यये प्रमुख हैं। उनकी मुख््य रचनाएँ— गीत-फ़रोश, खुशबू के शिलालेख, चकित है दुख, अँधेरी कविताएँ, बुनी हुई रस््सी, कवितांतर, शतदल, गांधी-पंचशती, त्रिकाल ससंध््या आदि हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('1d506e22-2be2-4059-abed-1e5be0d99927', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुनी हुई रस््सी (कविता संग्रह) पर उन््हें साहित््य अकादमी पुरस्कार मिला है। भवानीप्रसाद मिश्र ने राष्‍ट्रभाषा प्रचार समिति में कार््य कियया और सन् 1952–55 तक हैदराबाद से प्रकाशित हिंदी की लोकप्रियय साहित््ययिक पत्रिका कल्पना का संपादन भी कियया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('5452bc77-fe5f-4fe3-9036-2d9ecbba6aa1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सन् 1955–58 के बीच वे आकाशवाणी के हिंदी कार््यक्रमों से संबद्ध रहे। उन््होंने ससंपूर््ण गांधी वाङ्मयय का भी संपादन कियया। सन् 1985 में उनका निधन हो गयया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
