  ('3959c117-1594-4ebe-9254-e8331970a1f9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सन् 1955–58 के बीच वे आकाशवाणी के हिंदी कार््यक्रमों से संबद्ध रहे। उन््होंने ससंपूर््ण गांधी वाङ्मयय का भी संपादन कियया। सन् 1985 में उनका निधन हो गयया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('7d3b4962-2b20-468b-8f7e-94bd8aa6613a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रससाद मिश्र ने ससन् 1942 के ‘भारत छोड़ो आंदोलन’ में सक्रियय रूप ससे भाग लियया जिससके चलते ब्रिटिश ससरकार ने उन््हें तीन वर््ष के लिए कारावासस का दंड दियया। 1942 के स््ववाधीनता आंदोलन के ससमयय जेल में रहते हुए ही उन््होंने ‘घर की ययाद’ कविता लिखी। परिवार की स्ममृति ही इसस कविता की केेंद्रीयय ससंवेदना है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('d3a74cb4-0012-4049-aa37-8693d30d8258', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कारावासस के ससमयय घर को ययाद करते हुए कवि की स्ममृति में उनके परिजन एक-एक करके सम्‍म‍िलित होते चले जाते हैं। कवि ससावन के बादल द्ारा परिवार को ससंदेश भेज रहा है और उसससे आग्रह करता है कि वह उन््हें जेल के कष्‍टों के विषयय में न बताए और ससांत््वना दे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('0b1b9326-3813-495a-b72d-35fe0d3a261a', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भवानीप्रसाद मिश्र का जन््म सन् 1913 में मध््य प्रदेश के होशंगाबाद (अब नर्मदापुरम) में हुआ था। साहित््य के साथ-साथ स्वाधीनता आंदोलन में जिन कवियोों की सक्रियय भागीदारी थी, उनमें यये प्रमुख हैं। उनकी मुख््य रचनाएँ— गीत-फ़रोश, खुशबू के शिलालेख, चकित है दुख, अँधेरी कविताएँ, बुनी हुई रस््सी, कवितांतर, शतदल, गांधी-पंचशती, त्रिकाल ससंध््या आदि हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('70400e6f-8062-4ea2-b177-876e9c469158', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुनी हुई रस््सी (कविता संग्रह) पर उन््हें साहित््य अकादमी पुरस्कार मिला है। भवानीप्रसाद मिश्र ने राष्‍ट्रभाषा प्रचार समिति में कार््य कियया और सन् 1952–55 तक हैदराबाद से प्रकाशित हिंदी की लोकप्रियय साहित््ययिक पत्रिका कल्पना का संपादन भी कियया। सन् 1955–58 के बीच वे आकाशवाणी के हिंदी कार््यक्रमों से संबद्ध रहे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('20201f0f-47dc-4cf0-a043-385803702b1f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन््होंने ससंपूर््ण गांधी वाङ्मयय का भी संपादन कियया। सन् 1985 में उनका निधन हो गयया। भवानीप्रससाद मिश्र ने ससन् 1942 के ‘भारत छोड़ो आंदोलन’ में सक्रियय रूप ससे भाग लियया जिससके चलते ब्रिटिश ससरकार ने उन््हें तीन वर््ष के लिए कारावासस का दंड दियया। 1942 के स््ववाधीनता आंदोलन के ससमयय जेल में रहते हुए ही उन््होंने ‘घर की ययाद’ कविता लिखी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 4, NULL),
  ('9985f40b-08ee-460a-bc5e-eaf661daff53', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज पानी गिर रहा है, बहुत पानी गिर रहा है, रात-भर गिरता रहा है, प्राण मन घिरता रहा है, अब सबेरा हो गयया है, कब सबेरा हो गयया है, ठीक से मैंने न जाना, बहुत सोकर सिर््फ माना— क््योंकि बादल की अँधेरी, है अभी तक भी घनेरी, अभी तक चुपचाप है सब, रातवाली छाप है सब,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('99427c8f-0c82-430c-b47f-b097f2d500d3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गिर रहा पानी झरा-झर, हिल रहे पत्े हरा-हर, बह रही है हवा सर-सर, काँपते हैं प्राण थर-थर, बहुत पानी गिर रहा है, घर नजर में तिर रहा है, घर कि मुझसे दूर है जो, घर खुशी का पूर है जो,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4e4126bb-fdd1-485f-a70c-b87cc596eae6', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर कि घर में चार भाई, माययके में बहिन आई, बहिन आई बाप के घर, हायय रे परिताप के घर! घर की याद घर की याद आज का दिन दिन नहीं है, क््योंकि इसका छिन नहीं है, एक छिन सौ बरस है रे, हायय कैसा तरस है रे,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ffe53613-2d61-45be-9848-20e1d2e431c1', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर कि घर में सब जुड़े हैं, सब कि इतने कब जुड़े हैं, चार भाई चार बहिनें भुजा भाई प््यार बहिनें,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('570faae7-61b1-48e9-a457-8fcbdc5077d8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और माँ बिन-पढ़ी मेरी, दुख में वह गढ़ी मेरी, माँ कि जिसकी गोद में सिर, रख लियया तो दुख नहीं फिर, माँ कि जिसकी स्नेह-धारा का यय हाँ तक भी पसारा, उसे लिखना नहीं आता, जो कि उसका पत्र पाता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8d7c1979-c021-4dca-a183-d6ee7b5043f0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और पानी गिर रहा है, घर चतुर््ददिक् घिर रहा है, पिताजी भोले बहादुर, वज्र-भुज नवनीत-सा उर, पिताजी जिनको बुढ़ापा, एक क्षण भी नहीं व््यापा, जो अभी भी दौड़ जाएँ, जो अभी भी खिलखिलाएँ,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9d190c05-a484-4fc9-88c1-9b06b989aa41', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज पानी गिर रहा है, बहुत पानी गिर रहा है, रात-भर गिरता रहा है, प्राण मन घिरता रहा है, घर नजर में तिर रहा है, घर कि मुझसे दूर है जो, घर खुशी का पूर है जो,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5946478c-3bd4-49a4-b1f9-f8c7f0546234', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$माययके में बहिन आई, बहिन आई बाप के घर, हायय रे परिताप के घर! घर की याद घर की याद आज का दिन दिन नहीं है, क््योंकि इसका छिन नहीं है,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('15d2eb38-e7b2-4310-80e5-73f0a4b91a6b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चार भाई चार बहिनें भुजा भाई प््यार बहिनें, और माँ बिन-पढ़ी मेरी, दुख में वह गढ़ी मेरी,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('afc60751-7287-4e2e-99e0-d9bf69745aba', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$माँ कि जिसकी गोद में सिर, रख लियया तो दुख नहीं फिर, माँ कि जिसकी स्नेह-धारा का यय हाँ तक भी पसारा, उसे लिखना नहीं आता, जो कि उसका पत्र पाता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3d190799-573b-440b-858c-186ad11e0d9f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पिताजी भोले बहादुर, वज्र-भुज नवनीत-सा उर, पिताजी जिनको बुढ़ापा, एक क्षण भी नहीं व््यापा, जो अभी भी दौड़ जाएँ, जो अभी भी खिलखिलाएँ,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('87ad1c33-fdd6-4f8f-a76c-24891ce9e079', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आज पानी गिर रहा है, बहुत पानी गिर रहा है, रात-भर गिरता रहा है, प्राण मन घिरता रहा है, अभी तक चुपचाप है सब, रातवाली छाप है सब, काँपते हैं प्राण थर-थर,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8a06e084-2491-4baf-894d-077f3abf39a3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$घर कि मुझसे दूर है जो, घर खुशी का पूर है जो, घर कि घर में चार भाई, माययके में बहिन आई, बहिन आई बाप के घर, हायय रे परिताप के घर!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
