  ('53294b91-ffbf-43fd-8c26-b4ce65a867d5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह तुम्हारा मन समझकर, और अपनापन समझकर, गयया है सो ठीक ही हैयय ह तुम्हारी लीक ही है,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d3cc8e11-f742-4c81-9d2e-45ec2a86c38b', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पाँव जो पीछे हटाता, कोख को मेरी लजाता, इस तरह होओ न कच्चे, रो पड़ेेंगे और बच्चे,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f0b227ac-3bdf-46d1-9fd4-c4b1ab1e902f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पिताजी ने कहा होगा, हायय, कितना सहा होगा, कहाँ, मैं रोता कहाँ हूँ, धीर मैं खोता, कहाँ हूँ,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0935fcc0-3d77-4cc7-acfe-1eadb655ea18', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गिर रहा है आज पानी, याद आता है भवानी, उसे थी बरसात प्यारी, रात दिन की झड़ी झारी,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d6a7a2d0-7c41-43a2-b165-8d84cff020b3', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$खुले सिर नंगे बदन वह, घूमता फिरता मगन वह, बड़े बाड़े में कि जाता, बीज लौकी का लगाता,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a5692451-cab4-42b0-9a9e-96d1b429ccbb', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुझे बतलाता कि बेला ने फलानी फूल झेला, तू कि उसके साथ जाती, आज इससे याद आती,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b9eb1794-0b63-4c7d-bd76-164633238878', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं न रोऊँगा — कहा होगा, और फिर पानी बहा होगा, दृश््य उसके बाद का रे, पाँचवें की याद का रे,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('09d0b5f0-79f2-4092-864e-5f4ff490d667', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$भाई पागल, बहिन पागल, और अम््ममा ठीक बादल, और भौजी और सरला, सहज पानी सहज तरला,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3352575d-73dc-46e4-9a49-09d5e312de9e', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शर्म से रो भी न पाएँ, खूब भीतर छटपटाएँ, आज ऐसा कुछ हुआ होगा आज सबका मन चुआ होगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('78a6e2ec-8cfc-4fd3-8876-d06d7450dbc0', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अभी पानी थम गयया है, मन निहाययत नम गयया है, एक-से बादल जमे हैं, गगन-भर फैले रमे हैं,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f36ab25f-902f-4c87-bf61-26629c11f50d', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$ढेर है उनका, न फाँकेें, जो कि किरनें झुकेें-झाँकेें, लग रहे हैं वे मुझे योों, माँ कि आँगन लीप दे ज््यों;$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('a1015ba5-2cbb-46dc-9fdd-1a0ed10366f8', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$गगन-आँगन की लुनाई दिशा के मन में समाई दश-दिशा चुपचाप है रे, स्वस्थ की लयय छाप है रे$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8f63ee7f-bdce-473c-a122-8f2974281444', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$झाड़ आँखें बंद करके साँस सुस््थथिर मंद करके, हिले बिन चुपके खड़े हैं, क्षितिज पर जैसे जड़े हैं$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
