  ('8d5891b0-753f-4014-be1c-5c691e94c8e9', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$पिताजी ने कहा होगा, हायय, कितना सहा होगा, कहाँ, मैं रोता कहाँ हूँ, धीर मैं खोता, कहाँ हूँ, गिर रहा है आज पानी, याद आता है भवानी,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
