  ('b6be1a70-d0b7-4de0-91e7-3c6ee2f7fac5', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और भौजी और सरला, सहज पानी सहज तरला, शर्म से रो भी न पाएँ, खूब भीतर छटपटाएँ, आज ऐसा कुछ हुआ होगा आज सबका मन चुआ होगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('70932b98-1ca4-45d5-8c6f-03bdfe0bca23', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अभी पानी थम गयया है, मन निहाययत नम गयया है, एक-से बादल जमे हैं, गगन-भर फैले रमे हैं, ढेर है उनका, न फाँकेें, जो कि किरनें झुकेें-झाँकेें,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ccf8a25c-5e15-44f7-9b01-596e34b5780f', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तू जरा-सा दुख कितना, सह सकेगा क््या कि इतना, और इस पर बस नहीं है, बस बिना कुछ रस नहीं है, हवा आई उड़ चला तू, लहर आई मुड़ चला तू, लगा झटका टूट बैठा, गिरा नीचे फूट बैठा, तू कि प्रियय से दूर होकर, बह चला रे पूर होकर, दुख भर क््या पास तेरे, अश्रु सिंचित हास तेरे!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
