  ('caa843af-a9ad-4674-95a8-d389ac444a29', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक पत्ता टूट जाए, बस कि धारा फूट जाए, एक हल्की चोट लग ले, दूध की नद्दी उमग ले, एक टहनी कम न हो ले, कम कहाँ कि ख़म न हो ले, ध््यान कितना फिक्र कितनी, डाल जितनी जड़ें उतनी!$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('6e3199fc-338e-4ae2-9b0b-f670678a7c5c', '8af718c6-ca11-482b-9d6b-832f2b767928', '78deb2fa-7e06-40ab-ac3b-a5eff8a65dce', '2a393490-3e65-4a05-9c70-e125e4fe853f', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस तरह का हाल उनका, इस तरह का ख््याल उनका, हवा, उनको धीर देना, यय ह नहीं जी चीर देना, हे सजीले हरे सावन, हे कि मेरे पुण््य पावन, तुम बरस लो वे न बरसें, पाँचवें को वे न तरसें,$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-42-550Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
